python3 -c "
import zipfile, re
from lxml import etree
NS={'hp':'http://www.hancom.co.kr/hwpml/2010/HWPML'}

def extract_texts(root):
    return [t.text or '' for t in root.xpath('.//hp:t', namespaces=NS)]

with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx','r') as z:
    for name in ['Contents/section0.xml','Contents/section1.xml']:
        xml = z.read(name)
        root = etree.fromstring(xml)
        texts = extract_texts(root)
        joined = '\n'.join([t for t in texts if t.strip()])
        print('====', name, '====')
        # Show key lines only
        for needle in ['점검 ID', '현장명', '주관', '점검일', '위험', '총평', '즉시 조치', '보고 대상', '1.', '2.', '3.']:
            for line in joined.split('\n'):
                if needle in line:
                    print(line)
        # Date checks
        if '2026-06-18' in joined:
            print('FOUND raw date string!')
        if '2026.06.18' in joined:
            print('FOUND dotted date string.')
        # Risk tier + note checks
        if 'High' in joined and 'High 즉시조치' not in joined:
            # may still have High in other contexts; print occurrences
            print('Risk tier occurrences:')
            for line in joined.split('\n'):
                if 'High' in line:
                    print('  ', line)
        # lineSegArray checks
        has_lineseg = root.xpath('.//hp:linesegarray | .//hp:lineSegArray', namespaces=NS)
        print('lineSegArray elements remaining:', len(has_lineseg))
"
